1	// The generator's scheduler run (tasks-dispatch DESIGN §5) — the whole of the
2	// queue's scheduled machinery: it decides at the anchor and files an issue
3	// only when there is work (#1115, decision §15.28).
4	//
5	// Four jobs: INSTANTIATE — when a recurring task's anchor comes, evaluate its
6	// precondition through the injectable `evaluate` seam and create the work
7	// item only on a yes (a no is a row on the schedule board; a read the
8	// scheduler cannot make fails OPEN and creates the item for the executor to
9	// decide); READY blocked items whose dependencies have resolved and whose
10	// not-before has passed; ADOPT the issues somebody marked for implementation;
11	// and RECLAIM dead executor claims. The executor still re-evaluates at pick
12	// (§6.4) — the board's verdict is a watermark, never a verdict carried
13	// forward. A task's FIRST window is a row too (#1215): first sight books it and
14	// files nothing, so adopting a task costs no open issue. Beside job 1, two
15	// sweeps: a one-time migration retiring the sleeping standing items both
16	// earlier models left open, and the reap of a standing item whose task is no
17	// longer declared at HEAD.
18	//
19	// The run's last act is the DRAIN GATE (§15.30): it reports whether it left
20	// anything pickable, and the workflow's drain job starts an executor only then —
21	// an idle hour costs this one run rather than two.
22	//
23	// `planSchedulerRun` is the decision core, kept injectable so it tests with fixtures; the
24	// CLI shell below wires the GitHub reads, the signal-collection seam, and applies the ops.
25	
26	import { pathToFileURL } from 'node:url';
27	import { isSuspended, suspendedNotice } from './suspend.mjs';
28	import { mostRecentAnchor, nextAnchor } from './anchors.mjs';
29	import { EXECUTING_LEASH_MS } from './leases.mjs';
30	import { swapStatus } from './apply-status.mjs';
31	import { isReleasable } from './readiness.mjs';
32	import { isQueueItem } from './read.mjs';
33	import { pickOrder } from './executor.mjs';
34	import { lastLivenessAt } from './heartbeat.mjs';
35	import {
36	  WORK_PREFIX, BLOCKED, READY, TASK_OBSOLETE,
37	  NEEDS_HUMAN_DECISION, isBlockingPark,
38	  STATUS_BLOCKED, STATUS_READY, STATUS_RUNNING_EXECUTOR, STATUS_RUNNING_AGENT,
39	  isStatus, isParked, statusOf,
40	  QUEUE_LABELS, EPISODE_MARKER, workItemTitle, parseWorkItemTitle, parseWorkItemBody, taskIdFromPath,
41	  workItemBody, labelNames, hasLabel, parseLastVerdict,
42	  ORIGIN_AD_HOC, ORIGIN_PLANNED, ORIGIN_LABELS, REQUEST_LABEL, parseRequestFields,
43	  parseBlockedBy, withMachineBlock,
44	} from './work-item.mjs';
45	import { VERDICT_NO, VERDICT_GO, VERDICT_FAIL_OPEN, SCHEDULE_PREFIX } from './schedule-board.mjs';
46	import { REQUEST_TASK_ID } from '../built-in-tasks.mjs';
47	
48	// The scheduler run owns the executing-leash reclaim because it is deterministic and
49	// hourly, which recovers a dead executor's item in ~2h rather than the janitor's
50	// ~25h (DESIGN §11, owner decision 6).
51	export { EXECUTING_LEASH_MS };
52	
53	const ms = (t) => (t == null ? null : new Date(t).getTime());
54	
55	// What a board row says for a task whose first window has not come: the reason
56	// column IS the whole record of the wait, so it names the instant being waited
57	// for — the one thing the born-blocked item it replaces carried.
58	const firstWindowReason = (window) => `first window at ${window} — a task is never run off-anchor on the repo that has just adopted it`;
59	
60	// The ops `planSchedulerRun` emits, each a label-and-body mechanic the shell applies:
61	//   { kind: 'dedupe',  issue, reason }            close, task:obsolete
62	//   { kind: 'create',  pack, task, labels, body } a task's standing item
63	//   { kind: 'ready',   issue }                    task:blocked -> task:ready
64	//   { kind: 'reclaim', issue, reason }            task:executing -> task:ready
65	//   { kind: 'adopt',   request, title, body, … }  a marked issue becomes an item
66	//   { kind: 'supersede', issue, request, reason } a parked prior run of a re-ask
67	//   { kind: 'retire-sleeping', issue, reason }    migration: a sleeping standing item closes
68	//   { kind: 'retire-orphan', issue, reason }      a standing item whose task is gone closes
69	//   { kind: 'board',   rows }                     rewrite the schedule board (rows changed)
70	//
71	// `items` is every `[claudinite-work]` issue the shell fetched (state=all for the
72	// scheduled families, open for the rest), each `{ number, title, body, state,
73	// labels, created_at, closed_at, updated_at }`. `stateOf(number)` answers the
74	// state of a `Blocked-by` target that may not be a work item at all; an unknown
75	// number is never treated as closed, so an unreadable blocker delays rather than
76	// releases (the convergence-not-prevention posture).
77	//
78	// `evaluate(task)` is the anchor-side ask (#1115): async, returning the
79	// precondition's verdict `{ run, reason, … }` or `{ error }` where the
80	// scheduler could not decide — a missing credential, a failed signal read, a
81	// throwing precondition. An error FAILS OPEN: the item is created exactly as
82	// the calendar-only model created it and the executor decides at pick. With
83	// no seam wired (`evaluate: null` — a fixture, or an older shell) every
84	// occurrence fails open the same way, which IS the old behaviour.
85	//
86	// `board` is the parsed schedule board: `{ rows: Map<taskKey, row> }` (see
87	// schedule-board.mjs), or null where it could not be read — which reads as
88	// absent and evaluates. Only a row whose verdict is `no` and whose lastAsked
89	// equals the current anchor suppresses a re-ask (F31).
90	export async function planSchedulerRun({
91	  tasks, items = [], requests = [], now, schedule, executingLeashMs = EXECUTING_LEASH_MS,
92	  stateOf = () => null, evaluate = null, board = null,
93	}) {
94	  const nowMs = ms(now);
95	  const ops = [];
96	  const closedByThisRun = new Set();
97	  const boardRows = new Map(board?.rows ?? []);
98	  let boardChanged = false;
99	  const writeRow = (key, frequency, lastAsked, verdict, reason) => {
100	    const prev = boardRows.get(key);
101	    // Only the authoritative columns count as change; the next-window column
102	    // is derived at render time and must never cause a rewrite by itself.
103	    if (prev && prev.lastAsked === lastAsked && prev.verdict === verdict && (prev.reason ?? '') === (reason ?? '')) return;
104	    boardRows.set(key, { task: key, frequency, lastAsked, verdict, reason: reason ?? '' });
105	    boardChanged = true;
106	  };
107	
108	  // ---- the one-time migration (#1115, #1215), and the orphan reap -------
109	  // A sleeping standing item — open, blocked, unqualified, a FUTURE Not-before,
110	  // no blockers — closes with its window seeded onto the board, whether it was
111	  // ROLLED there by the retired roll model (a `Last verdict` section says so, and
112	  // its own reason is what the row carries) or BORN blocked at adoption (no such
113	  // section: the row says which window it is waiting for). Either way the fact it
114	  // held open — "not now, next ask at X" — is what the board is for, and holding
115	  // an issue open to say it is the cost #1115 set out to remove.
116	  //
117	  // Idempotent: closed items never match again, and a seeded row is written only
118	  // where none exists. Untouched: items waiting on a blocker, which are somebody's
119	  // dependency rather than a window.
120	  //
121	  // Beside it, the orphan reap: a standing item whose `<pack>/<task>` is not
122	  // declared at HEAD can never execute — job 1 matches its family title-exact on
123	  // the declared id, so a legacy pack spelling is invisible to it, and job 2 would
124	  // otherwise ready the item at its Not-before and hand an executor a task path
125	  // that is not on disk. Guarded on a non-empty task list so an unreadable
126	  // declaration reaps nothing, and scoped to BLOCKED so nothing in flight is
127	  // touched — a ready orphan is picked within the hour and parks for a human,
128	  // which is visible rather than silent.
129	  //
130	  // Both are gated on the evaluation seam being wired, so a fixture driving the
131	  // calendar-only shape sees neither.
132	  if (evaluate) {
133	    const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
134	    for (const item of items) {
135	      if (item.state !== 'open' || !isStatus(item, STATUS_BLOCKED)) continue;
136	      const parsed = parseWorkItemTitle(item.title);
137	      if (!parsed || parsed.qualifier !== null) continue;
138	      const key = `${parsed.pack}/${parsed.task}`;
139	      const { notBefore, blockedBy } = parseWorkItemBody(item.body);
140	      if (blockedBy.length) continue;
141	
142	      if (!byId.has(key)) {
143	        if (!tasks.length) continue;
144	        closedByThisRun.add(item.number);
145	        ops.push({
146	          kind: 'retire-orphan', issue: item.number, pack: parsed.pack, task: parsed.task,
147	          reason: `Closing: \`${key}\` is no longer declared on this repository, so this item names a task `
148	            + 'that is not at HEAD and can never run. If the task came back under a new id, its own item is the live one.',
149	        });
150	        continue;
151	      }
152	
153	      const freq = byId.get(key).decl?.frequency ?? null;
154	      if (freq == null || freq === 'manual') continue; // not a standing item
155	      if (!notBefore || (ms(notBefore) ?? -Infinity) <= nowMs) continue;
156	      const verdict = parseLastVerdict(item.body);
157	      if (!boardRows.has(key)) {
158	        writeRow(key, freq,
159	          verdict?.at ?? mostRecentAnchor(freq, schedule, now).toISOString(),
160	          VERDICT_NO, verdict ? (verdict.reason ?? '') : firstWindowReason(notBefore));
161	      }
162	      closedByThisRun.add(item.number);
163	      ops.push({
164	        kind: 'retire-sleeping', issue: item.number, pack: parsed.pack, task: parsed.task,
165	        reason: verdict
166	          ? 'Closing: a declined occurrence now lives as a row on the schedule board '
167	            + `(\`${SCHEDULE_PREFIX}\`), not as a sleeping work item. The next ask happens at this task's next anchor.`
168	          : "Closing: a task's first window is now a row on the schedule board "
169	            + `(\`${SCHEDULE_PREFIX}\`), not an item held open until its anchor. The first ask happens at that anchor.`,
170	      });
171	    }
172	  }
173	
174	  // ---- job 1: instantiate — evaluate at the anchor; a yes files the item ----
175	  for (const task of tasks) {
176	    if (task.decl.frequency === 'manual') continue;
177	    const key = `${task.pack}/${task.id}`;
178	    const title = workItemTitle({ pack: task.pack, task: task.id });
179	    // The family is title-EXACT, which is also what makes it STRUCTURALLY the
180	    // standing family (§15.26): this task is on a calendar and the title carries no
181	    // qualifier, so a fan-out target or a request — qualified, both of them — is a
182	    // different title and neither suppresses nor consumes an occurrence (§3).
183	    const family = items.filter((i) => (i.title ?? '').trim() === title);
184	    // A park that is somebody's INBOX rather than a fault — a PR to approve, a
185	    // choice to make, a secret to set — does not hold the lane: it is neither this
186	    // task's standing item nor a duplicate of it, so it drops out here entirely and
187	    // the schedule goes on around it. A `failure` park (and any park an older engine
188	    // left unclassified) stays in, and holding the lane is the point.
189	    const open = family
190	      .filter((i) => i.state === 'open' && !closedByThisRun.has(i.number))
191	      .filter((i) => !isParked(i) || isBlockingPark(i))
192	      .sort((a, b) => a.number - b.number);
193	
194	    // F16 self-heal, FIRST: nothing documents that a REST list from another node
195	    // sees a creation seconds old, so a stale list can let a duplicate standing
196	    // item through. Assume it will happen rather than that it won't — close every
197	    // open family item but the oldest. Serialized by the scheduler run's concurrency group,
198	    // so this can never race itself.
199	    for (const dup of open.slice(1)) {
200	      closedByThisRun.add(dup.number);
201	      ops.push({
202	        kind: 'dedupe', issue: dup.number, pack: task.pack, task: task.id,
203	        reason: `a duplicate standing item for ${task.pack}/${task.id} — #${open[0].number} is this task's standing item`,
204	      });
205	    }
206	    if (open.length) continue; // the standing item already exists
207	
208	    const anchor = mostRecentAnchor(task.decl.frequency, schedule, now);
209	    const anchorMs = anchor.getTime();
210	    // The occurrence guard has TWO halves (F13): an item CREATED at-or-after the
211	    // anchor covers this occurrence — and so does an item CLOSED at-or-after it,
212	    // because an item created in an earlier period that ran and closed today
213	    // consumed today's occurrence. With the created_at half alone, the very next
214	    // scheduler run after such a close creates a second item for the same occurrence: a
215	    // double execution. An item this very run retired counts as closed now.
216	    const covered = family.some((i) =>
217	      (ms(i.created_at) ?? -Infinity) >= anchorMs
218	      || (ms(i.closed_at) ?? -Infinity) >= anchorMs
219	      || closedByThisRun.has(i.number));
220	    if (covered) continue;
221	
222	    // FIRST SIGHT of a task on this repo: it must not run off-anchor on the
223	    // least-proven repo (S25), and under "no work, no item" that wait is a board
224	    // row rather than an item held open until the anchor (#1215). The board is
225	    // half of what makes it first sight — an item this task once had is the other
226	    // half, and either one alone would re-book the window forever.
227	    //
228	    // The cost, stated: for a task that has never yet run, a board deleted mid-
229	    // window reads as first sight again and costs one skipped occurrence, where
230	    // the board's own header promises one redundant evaluation. Past a task's
231	    // first run its family is non-empty forever and that promise holds again.
232	    const firstEver = family.length === 0 && !boardRows.has(key);
233	    if (evaluate) {
234	      // The watermark: this anchor was already asked and DECLINED. Scoped to
235	      // declined rows only (F31, and see schedule-board.mjs): a go/fail-open
236	      // verdict's cover is the item it created, judged by the guards above.
237	      const row = boardRows.get(key);
238	      if (row && row.verdict === VERDICT_NO && (ms(row.lastAsked) ?? NaN) === anchorMs) continue;
239	
240	      if (firstEver) {
241	        // Booked against the anchor it is declining, so the watermark above holds
242	        // the rest of this window and the first real ask happens at the next one.
243	        writeRow(key, task.decl.frequency, anchor.toISOString(), VERDICT_NO,
244	          firstWindowReason(nextAnchor(task.decl.frequency, schedule, now).toISOString()));
245	        continue;
246	      }
247	
248	      const verdict = (await evaluate(task)) ?? {};
249	      const lastAsked = anchor.toISOString();
250	      if (verdict.error) {
251	        // Fail open: never fewer runs because a read failed — the executor,
252	        // which holds the credentials, decides at pick (§6.4).
253	        writeRow(key, task.decl.frequency, lastAsked, VERDICT_FAIL_OPEN, verdict.error);
254	      } else if (verdict.run !== true) {
255	        // No work, no item: the row is the whole record of this occurrence.
256	        writeRow(key, task.decl.frequency, lastAsked, VERDICT_NO, verdict.reason || 'no work');
257	        continue;
258	      } else {
259	        writeRow(key, task.decl.frequency, lastAsked, VERDICT_GO, verdict.reason || '');
260	      }
261	    }
262	    // Reachable with a first sight only where no seam is wired (a fixture, an
263	    // older shell): there the calendar-only model's born-blocked item is still
264	    // the whole of the off-anchor guard.
265	    const notBefore = firstEver ? nextAnchor(task.decl.frequency, schedule, now).toISOString() : null;
266	    ops.push({
267	      kind: 'create', pack: task.pack, task: task.id, title,
268	      // THE ORIGIN, worn for the item's whole life beside whatever status it holds
269	      // (DESIGN §3): the schedule filed this one, so it is `planned`.
270	      labels: [ORIGIN_PLANNED, firstEver ? BLOCKED : READY],
271	      body: workItemBody({
272	        taskPath: task.taskPath,
273	        notBefore,
274	        context: firstEver
275	          ? [`This task's first work item on this repo — born blocked until its first real anchor (${notBefore}), so adoption never runs it off-anchor.`]
276	          : [],
277	      }),
278	      notBefore,
279	    });
280	  }
281	
282	  // ---- job 2: ready whatever is due (any origin) --------------------------
