354	    });
355	  }
356	
357	  // ---- job 3: reclaim dead executor claims (DESIGN §11) -------------------
358	  const policyOf = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t.decl.on_interrupt ?? 'requeue']));
359	  for (const item of items) {
360	    if (item.state !== 'open' || !isStatus(item, STATUS_RUNNING_EXECUTOR)) continue;
361	    // SILENCE IS THE HOLDER'S, not the issue's (§11, #924). `updated_at` moves on
362	    // any comment — including the one an executor that LOST the claim race writes
363	    // on its way out — which defers the reclaim of an item nobody is working on.
364	    // `livenessAt` is the shell's read of the holder's last claim or heartbeat;
365	    // where it could not be read, the issue's own clock is the fallback, which is
366	    // the pre-heartbeat behaviour and errs toward waiting.
367	    const lastSign = ms(item.livenessAt) ?? ms(item.updated_at) ?? ms(item.created_at) ?? nowMs;
368	    const silentFor = nowMs - lastSign;
369	    if (silentFor < executingLeashMs) continue;
370	    // WHICH TASK, on a marked issue: its title is the person's own, so the id comes
371	    // from the worker path its machine block names — the same fallback the janitor's
372	    // rules use. Without it every ad-hoc item reads as an unknown task and re-queues,
373	    // and `implement-request`, the one task that declares `needs-human`, is exactly
374	    // the task every ad-hoc item runs.
375	    const parsed = parseWorkItemTitle(item.title) ?? taskIdFromPath(parseWorkItemBody(item.body).taskPath);
376	    const minutes = Math.round(executingLeashMs / 60e3);
377	    // `on_interrupt: 'needs-human'` is the at-most-once dial: a task that cannot
378	    // promise a safe re-run is not re-queued by a recovery path — it goes to a
379	    // human, who decides whether the interrupted run left anything behind.
380	    const oneShot = parsed && policyOf.get(`${parsed.pack}/${parsed.task}`) === 'needs-human';
381	    ops.push({
