383	      // what the human is being asked for — whether the interrupted run left
384	      // anything behind, and so whether this re-queues at all.
385	      kind: 'reclaim', issue: item.number, to: oneShot ? NEEDS_HUMAN_DECISION : READY,
386	      reason: oneShot
