401	// --- the forced wake (DESIGN §8) ----------------------------------------------
402	
403	// Which standing items a `wake` dispatch names. Forcing a scheduled task IS waking
404	// its standing item, and this is that same lever reached from OUTSIDE the repo: the
405	// fleet enforcer dispatches this workflow with the task ids it wants run now, and
406	// the member wakes its own items with its own token. The enforcer therefore needs
407	// no issue access anywhere — the fan-out model the enforcer's sweeps are built on, where
408	// the enforcer dispatches and the member executes.
409	//
410	// An id is `pack/task` or a bare `task` resolved against this repo's own discovered
411	// tasks, so a caller spanning many members never has to know any one member's pack
412	// layout. Every id that matches nothing comes back in `unmatched`: a force whose
413	// report counts only what it woke reads as coverage it did not have.
414	//
415	// An item already in flight (`task:ready`, `task:executing`, `task:agent`) is left
416	// alone and reported as `already`, never re-woken — an episode boundary dropped on
417	// a live claim is exactly the livelock F18 describes.
418	//
419	// WHEN THE STANDING ITEM DOES NOT EXIST, forcing MINTS it (§8's other lever). A
420	// task that completes closes its item, and the next one appears only at the next
421	// anchor — so between the two there is nothing to wake, and that gap is the common
422	// case rather than an edge: a daily task is missing its item for most of the day.
423	// A force that reported "nothing to wake" there would fail on most members most of
424	// the time, which is precisely what a fleet-wide converge lever must not do. The
425	// minted item is an ordinary standing item — same title, no qualifier: it consumes
426	// the CURRENT occurrence, so the scheduler run does not then create a second one beside it,
427	// and it leaves the next anchor's occurrence untouched.
428	export function planWake(spec, tasks = [], items = []) {
429	  const ids = String(spec ?? '').split(/[\s,]+/).map((s) => s.trim()).filter(Boolean);
430	  const wake = []; const create = []; const already = []; const unmatched = [];
431	  for (const id of ids) {
432	    const [a, b] = id.includes('/') ? id.split('/') : [null, id];
433	    const owners = tasks.filter((t) => t.id === b && (a === null || t.pack === a));
434	    if (owners.length !== 1) {
435	      unmatched.push({ id, why: owners.length ? `${owners.length} declared packs own a "${b}" task — name it as pack/task` : 'no declared pack owns a task by that name' });
436	      continue;
437	    }
438	    const owner = owners[0];
439	    const { pack, id: task } = owner;
440	    const item = items.find((i) => {
441	      if (i.state !== 'open') return false;
442	      const parsed = parseWorkItemTitle(i.title);
443	      return parsed && parsed.pack === pack && parsed.task === task;
444	    });
445	    if (!item) { create.push({ id: `${pack}/${task}`, pack, task, taskPath: owner.taskPath }); continue; }
446	    if (IN_FLIGHT.includes(statusOf(item))) { already.push({ id, issue: item.number }); continue; }
447	    wake.push({ id: `${pack}/${task}`, issue: item.number });
448	  }
449	  return { wake, create, already, unmatched };
450	}
