463	// --- CLI: the thin I/O shell the vendored scheduler run workflow invokes ---------------
464	// Reads the work-item list, plans, applies. All GitHub access is the Action's
465	// GITHUB_TOKEN. Dormancy is the first gate, before any read — a project that has
466	// said it is out of the recurring work should not pay for the list that proves it.
467	
468	// Every WORK ITEM, state=all, via the ISSUES list API — never the search index
469	// (S6/F11: search is eventually consistent, and a family list that misses a
470	// just-created item mints a duplicate standing item). Bounded by the scheduled
471	// families' need for closed history: closed items are only interesting back to the
472	// widest period, so the listing stops once it is past that.
473	//
474	// MEMBERSHIP IS `isQueueItem`, the shared predicate, and not the title prefix
475	// (#1497). An adopted marked issue IS an item under the one-issue model (DESIGN
476	// §16.1) and keeps the person's own title forever, so a prefix test drops exactly
477	// that class — and job 2 is the ONLY site that releases a blocked item, so an
478	// ad-hoc item born blocked on a `Not-before:` sat sleeping past its instant with
479	// nothing left to wake it (#1267, #1349, #1351, #1396). The executor and the
480	// janitor already read the queue through this predicate; this list was the one that
481	// did not.
482	export async function listWorkItems(gh, repo, { since = null } = {}) {
483	  const out = [];
484	  for (let page = 1; ; page += 1) {
485	    const q = `state=all&sort=created&direction=desc&per_page=100&page=${page}`
486	      + (since ? `&since=${encodeURIComponent(since)}` : '');
487	    const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
488	    // A page that could not be read is not the end of the list. Breaking on it
489	    // truncates the queue mid-pagination and the run plans against the remainder:
490	    // a standing item whose page never arrived reads as absent, and the run mints a
491	    // second one beside it.
492	    if (status !== 200 || !Array.isArray(json)) {
493	      throw new Error(`could not list work items in ${repo} at page ${page} (${status}) — a truncated queue is not a shorter one`);
494	    }
495	    if (json.length === 0) break;
496	    for (const i of json) {
497	      if (i.pull_request) continue;
498	      if (!isQueueItem(i)) continue;
499	      out.push({
500	        number: i.number, title: i.title, body: i.body ?? '', state: i.state,
501	        labels: labelNames(i), created_at: i.created_at, closed_at: i.closed_at,
502	        updated_at: i.updated_at,
503	      });
504	    }
505	    if (json.length < 100) break;
506	  }
507	  return out;
508	}
