510	// Every OPEN issue carrying the mark and NO status, via the ISSUES list API
511	// filtered by label — never the search index, for the same reason the work-item
512	// list is not (S6/F11): a mark this list misses is a request that silently waits an
513	// hour, and one it misses TWICE is a request nobody notices was never picked up.
514	//
515	// The author's push permission comes back with each issue, because adoption gates
516	// the body's parameters on it (§16.7) and the payload's `author_association` is not
517	// that fact: `MEMBER` is any org member whatever their repo permission, and
518	// `COLLABORATOR` includes read-only collaborators (F30). A read that cannot answer
519	// leaves the flag `null`, which gates the parameters off — the safe end of a field
520	// that chooses a task, a model, or the right to land a change without review.
521	export async function listMarkedIssues(gh, repo, { permissionOf = null } = {}) {
522	  const out = [];
523	  const push = permissionOf ?? (async (login) => {
524	    const res = await gh(`/repos/${repo}/collaborators/${encodeURIComponent(login)}/permission`);
525	    if (res.status === 404) return false;
526	    if (res.status !== 200) return null;
527	    return ['admin', 'maintain', 'write'].includes(res.json?.role_name ?? res.json?.permission ?? 'none');
528	  });
529	  const cache = new Map();
530	  // ONE QUERY PER MARK, unioned here. GitHub's `labels` filter is CONJUNCTIVE — a
531	  // comma-separated list selects the issues carrying EVERY name on it — so asking
532	  // for both marks at once asks for issues wearing both, which nothing does. The
533	  // retired `claude-task` spelling keeps working for whoever has it in muscle memory
534	  // or in a template, decoded forever like every legacy spelling (§4), and that
535	  // costs a second listing rather than a wider one.
536	  const seen = new Map();
537	  for (const label of [ORIGIN_AD_HOC, REQUEST_LABEL]) {
538	    for (let page = 1; ; page += 1) {
539	      const q = `state=open&labels=${encodeURIComponent(label)}&per_page=100&page=${page}`;
540	      const { status, json } = await gh(`/repos/${repo}/issues?${q}`);
541	      // A list that could not be READ is not a list that is EMPTY, and the two are
542	      // indistinguishable downstream: adoption simply finds nothing to do and the run
543	      // reports success. Every request then waits for a person to notice, which is
544	      // the one thing this lane exists so nobody has to do.
545	      if (status !== 200 || !Array.isArray(json)) {
546	        throw new Error(`could not list open issues marked \`${label}\` in ${repo} (${status}) — an unreadable request list is not an empty one`);
547	      }
548	      if (json.length === 0) break;
549	      for (const i of json) {
550	        if (i.pull_request) continue;
551	        // A filed work item wearing the mark is not a request awaiting adoption: it is
552	        // already an item, and re-adopting one would rewrite its body under the run
553	        // holding it.
554	        if ((i.title ?? '').startsWith(WORK_PREFIX)) continue;
555	        // ANY status means this mark has been adopted — the exactly-once guard (§16.3).
556	        // Filtering here rather than in the plan keeps the permission reads to the
557	        // issues actually awaiting adoption.
558	        if (statusOf(i) !== null) continue;
559	        // An issue wearing both spellings comes back from both listings; it is one
560	        // request, and adopting it twice would rewrite the body of the item the first
561	        // adoption just made.
562	        if (seen.has(i.number)) continue;
563	        const author = i.user?.login ?? null;
564	        if (author && !cache.has(author)) cache.set(author, await push(author));
565	        seen.set(i.number, {
566	          number: i.number, title: i.title, body: i.body ?? '', state: i.state,
567	          labels: labelNames(i), author, authorHasPush: author ? cache.get(author) : null,
568	        });
569	      }
570	      if (json.length < 100) break;
571	    }
572	  }
573	  out.push(...seen.values());
574	  return out;
575	}
