577	// Which `Blocked-by` targets this run still has to read. A target need not be a
578	// work item — a fan-in blocks on whatever its children are — so states come from
579	// the fetched items first and a direct read otherwise, and `known` is what has
580	// already been answered.
581	//
582	// A marked issue's blockers count the same way: adoption decides whether the item
583	// it births is born blocked or ready, and an unread state is never `closed`, so a
584	// missing read delays the request rather than releasing it (§16.11).
585	//
586	// Extracted from `main` so it can be called at all. Nothing else here drives
587	// `main`, whose body is I/O against a live Action, so an identifier it names and
588	// never imports resolves at run time or not at all — and the request half went
589	// three days without executing once, behind an adoption list that was always
590	// empty (#1354).
591	export function blockersToResolve(items, requests, known) {
592	  const wanted = new Set();
593	  for (const i of items) {
594	    if (i.state !== 'open' || !isStatus(i, STATUS_BLOCKED)) continue;
595	    for (const n of parseWorkItemBody(i.body).blockedBy) if (!known.has(n)) wanted.add(n);
596	  }
597	  for (const r of requests) {
598	    for (const n of parseBlockedBy(r.body)) if (!known.has(n)) wanted.add(n);
599	  }
600	  return wanted;
601	}
