700	  // milliseconds earlier (#1340). The run does not need the read to know what it
701	  // wrote, so every issue it readies is recorded here and counted regardless.
702	  const readied = new Set();
703	
704	  for (const op of ops) {
705	    if (op.kind === 'create') {
706	      const res = await createIssue(gh, repo, { title: op.title, body: op.body, labels: op.labels });
707	      if (res.number) {
708	        if (op.labels.includes(READY)) readied.add(res.number);
709	        console.log(`- created #${res.number} ${op.pack}/${op.task} [${op.labels.join(' ')}]`);
710	      } else console.log(`! could not create the work item for ${op.pack}/${op.task}: ${res.status}`);
711	    } else if (op.kind === 'ready') {
712	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_BLOCKED, READY);
713	      readied.add(op.issue);
714	      console.log(`- readied #${op.issue}`);
715	    } else if (op.kind === 'reclaim') {
716	      // The reclaim comment is also the EPISODE BOUNDARY: every claim before it is
717	      // dead, and arbitrating over dead claims makes one outrank every future live
718	      // claimant — the item then livelocks through reclaim cycles forever (F18).
719	      await comment(gh, repo, op.issue, `${EPISODE_MARKER}\n${op.reason}`);
720	      await swapStatus({ addLabel, removeLabel }, gh, repo, { number: op.issue }, STATUS_RUNNING_EXECUTOR, op.to);
721	      if (op.to === READY) readied.add(op.issue);
722	      console.log(`- reclaimed #${op.issue} -> ${op.to}`);
723	    } else if (op.kind === 'adopt') {
724	      // THE ISSUE IS THE ITEM, so adoption writes to it rather than filing anything:
725	      // the machine block first, the status second. That order is what makes a torn
726	      // adoption safe — a block with no status is re-adopted by the next scheduler
727	      // run (which rewrites it), while a status with no block would name no task.
728	      const res = await gh(`/repos/${repo}/issues/${op.request}`, { method: 'PATCH', body: { body: op.body } });
729	      if (res.status !== 200) {
730	        console.log(`! could not adopt #${op.request}: its body could not be written (${res.status})`);
731	        process.exitCode = 1;
732	        continue;
733	      }
734	      if (op.origin) await addLabel(gh, repo, op.request, op.origin);
735	      await addLabel(gh, repo, op.request, op.status);
736	      await comment(gh, repo, op.request,
737	        `Queued: a run of \`${op.task}\` for this issue${op.model ? `, at the \`${op.model}\` family` : ''}.\n\n`
738	        + (op.blockedBy.length
739	          ? `It is **blocked** on ${op.blockedBy.map((n) => `#${n}`).join(', ')} — it enters the queue once they close.\n\n`
740	          : '')
741	        + (op.notBefore ? `It waits until ${op.notBefore} before entering the queue.\n\n` : '')
742	        + (op.merge
743	          ? `The run implements this issue and opens a pull request; it may land that pull request itself only when the diff sits inside the authorized policy (\`${op.merge}\`), and leaves a wider one for review. `
744	          : 'The run implements this issue and opens a pull request for review — it never merges one. ')
745	        + (op.ungated
746	          ? '\n\nThe `Task:`/`Model:`/`Automerge:` fields in this body were ignored: they are honoured only for an author with push access on this repository, so this run takes the defaults. '
747	          : '')
748	        + `To withdraw the request before it starts, remove the \`${ORIGIN_AD_HOC}\` mark and the status beside it.`);
749	      console.log(`- adopted #${op.request} for ${op.task} (${op.model ?? 'default model'}${op.blockedBy.length ? `, blocked on ${op.blockedBy.map((n) => `#${n}`).join(' ')}` : ''}${op.merge ? `, may merge: ${op.merge}` : ''})`);
750	    } else if (op.kind === 'supersede') {
751	      await comment(gh, repo, op.issue, op.reason);
752	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
753	      await closeIssue(gh, repo, op.issue, 'not_planned');
754	      console.log(`- superseded #${op.issue} — #${op.request} was re-marked`);
755	    } else if (op.kind === 'dedupe') {
756	      await comment(gh, repo, op.issue, op.reason);
757	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
758	      await closeIssue(gh, repo, op.issue, 'not_planned');
759	      console.log(`- deduped #${op.issue}`);
760	    } else if (op.kind === 'retire-orphan') {
761	      await comment(gh, repo, op.issue, op.reason);
762	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
763	      await closeIssue(gh, repo, op.issue, 'not_planned');
764	      console.log(`- reaped #${op.issue} — ${op.pack}/${op.task} is not declared at HEAD`);
765	    } else if (op.kind === 'retire-sleeping') {
766	      await comment(gh, repo, op.issue, op.reason);
767	      await addLabel(gh, repo, op.issue, TASK_OBSOLETE);
768	      await closeIssue(gh, repo, op.issue, 'not_planned');
769	      console.log(`- retired sleeping item #${op.issue} ${op.pack}/${op.task} onto the schedule board`);
770	    } else if (op.kind === 'board') {
771	      if (!boardFetch.readable) {
772	        // Never write what could not be read: a blind create could mint a
773	        // second board. The rows this run derived are re-derived next run.
774	        console.log('! the schedule board could not be listed — skipping its rewrite this run');
775	      } else if (boardFetch.issue) {
776	        const res = await gh(`/repos/${repo}/issues/${boardFetch.issue.number}`, {
777	          method: 'PATCH',
778	          body: { body: renderScheduleBoard(op.rows, { now, schedule: config.taskScheduler }) },
779	        });
780	        console.log(res.status === 200
781	          ? `- schedule board #${boardFetch.issue.number} updated (${op.rows.length} row(s))`
782	          : `! could not update schedule board #${boardFetch.issue.number}: ${res.status}`);
783	      } else {
784	        const res = await createIssue(gh, repo, {
785	          title: scheduleBoardTitle(),
786	          body: renderScheduleBoard(op.rows, { now, schedule: config.taskScheduler }),
787	          labels: [],
788	        });
789	        console.log(res.number
790	          ? `- schedule board created as #${res.number} (${op.rows.length} row(s))`
791	          : `! could not create the schedule board: ${res.status}`);
792	      }
793	    }
794	  }
795	
796	  if (!ops.length) console.log('- nothing to do: every task has its standing item, nothing is due, nothing is marked, no claim is dead');
797	
798	  // The forced wake, last: an item this run just instantiated is wakeable in the
799	  // same run, so a force never has to be pressed twice. The drain job that follows
800	  // picks up whatever this readies.
801	  const spec = process.env.CLAUDINITE_WAKE ?? '';
802	  if (spec.trim()) {
803	    const { wakeItem } = await import('./create-work-item.mjs');
804	    // Re-read: the ops above may have created or readied the very items named.
805	    const current = await listWorkItems(gh, repo, { since });
806	    const { wake, create, already, unmatched } = planWake(spec, tasks, current);
807	    for (const w of wake) {
808	      const res = await wakeItem(gh, repo, w.issue);
809	      if (res.ok) readied.add(w.issue);
810	      console.log(res.ok ? `- woke #${w.issue} ${w.id}` : `! could not wake #${w.issue} ${w.id}: ${res.error}`);
811	    }
812	    if (create.length) await ensureLabels(gh, repo, QUEUE_LABELS);
813	    for (const c of create) {
814	      const res = await createIssue(gh, repo, {
815	        title: workItemTitle({ pack: c.pack, task: c.task }),
816	        body: workItemBody({ taskPath: c.taskPath, context: [FORCED_WAKE_CONTEXT] }),
817	        // A forced mint stands in for the occurrence a schedule would have filed, so
818	        // it wears the same origin: the task IS on a calendar, and this item is its
819	        // current occurrence (§8).
820	        labels: [ORIGIN_PLANNED, READY],
821	      });
822	      if (res.number) {
823	        readied.add(res.number);
824	        console.log(`- created #${res.number} ${c.id} (forced: it had no open standing item)`);
825	      } else { console.log(`! could not create a work item for ${c.id}: ${res.status}`); process.exitCode = 1; }
826	    }
827	    for (const a of already) console.log(`- ${a.id} is already in flight on #${a.issue} — left alone`);
828	    for (const u of unmatched) console.log(`! nothing woken for "${u.id}": ${u.why}`);
829	    // A force that woke nothing is a failed force, and a green run saying so in a
830	    // log line is how it goes unnoticed by the fleet lever that pressed it.
831	    if (unmatched.length) process.exitCode = 1;
832	  }
833	
834	  // LAST, AFTER THE WAKE: whether this run leaves anything for an executor to do.
835	  await announcePickable(gh, repo, tasks, readied);
836	}
837	
838	// THE DRAIN GATE (§15.30). Every workflow run is a billed invocation whatever it
839	// finds — Actions rounds each job's minutes up — so the drain job dispatches an
840	// executor only when this run's parting look at the queue found something
841	// pickable. On a quiet repo that is the difference between 24 executor runs a day
842	// and none.
843	//
844	// This is the run's LAST act, after the forced wake: a wake readies items, and a
845	// look taken before it would send the hour's forced work to the next cron fire.
846	//
847	// The delivery is unweakened by the gate. A label event may be lost, and what a
848	// lost event would have delivered is exactly what this look sees — the queue
849	// itself, read live, by the same pick rule the executor applies. Where the
850	// output cannot be written (a run outside Actions, an older member workflow that
851	// maps no output) the drain job's own default decides, and the run says which
852	// happened rather than going quiet about it.
853	// THE VERDICT IS A UNION, not a read. What the list returns is one source; what
854	// this run itself readied is the other, and the second needs no confirmation —
855	// GitHub's issue list is eventually consistent, so an item created milliseconds
856	// earlier can be absent from it (#1340). Trusting the read alone left a forced
857	// `update` sitting `task:ready` until the next cron fire on three members at once.
858	// Ordering stays the executor's job: this only decides whether to start one.
859	export function pickableCount(open, readiedThisRun = [], opts = {}) {
860	  const listed = pickOrder(open, opts).map((i) => i.number);
861	  return new Set([...listed, ...readiedThisRun]).size;
862	}
863	
864	async function announcePickable(gh, repo, tasks, readiedThisRun = new Set()) {
865	  const { listOpenWorkItems } = await import('./read.mjs');
866	  const byId = new Map(tasks.map((t) => [`${t.pack}/${t.id}`, t]));
867	  const byPath = new Map(tasks.map((t) => [t.taskPath, `${t.pack}/${t.id}`]));
868	  const pickable = pickableCount(await listOpenWorkItems(gh, repo), readiedThisRun, {
869	    taskAfter: (id) => byId.get(id)?.decl?.schedule_after ?? [],
870	    frequencyOf: (id) => byId.get(id)?.decl?.frequency ?? null,
871	    pathTo: (p) => byPath.get(p) ?? null,
872	  });
873	  console.log(pickable
874	    ? `- ${pickable} item(s) pickable — the drain job dispatches an executor`
875	    : '- nothing pickable — no executor is dispatched this run');
876	  const out = process.env.GITHUB_OUTPUT;
877	  if (!out) return;
878	  const { appendFileSync } = await import('node:fs');
879	  appendFileSync(out, `pickable=${pickable ? 'true' : 'false'}\n`);
880	}
881	
882	// Run only when invoked directly (the workflow's `node scheduler-run.mjs`), never on
883	// import. Exported as well, because `tick.mjs` beside this file is a fielded entry
884	// point that must be able to start the same run without being this module.
885	export { main as runSchedulerRun };
886	if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
887	  main().catch((e) => { console.error(e); process.exit(1); });
888	}
889	
890	export { parseWorkItemTitle };
891

